const state = await appStore.getState();

const STORE_KEY = "habitTracker";
const todayKey = formatDateKey(new Date());

const els = {
  todayLabel: document.querySelector('[data-role="today-label"]'),
  doneCount: document.querySelector('[data-role="done-count"]'),
  totalCount: document.querySelector('[data-role="total-count"]'),
  statsSub: document.querySelector('[data-role="stats-sub"]'),
  progressFill: document.querySelector('[data-role="progress-fill"]'),
  habitInput: document.querySelector('[data-role="habit-input"]'),
  addBtn: document.querySelector('[data-role="add-btn"]'),
  addHint: document.querySelector('[data-role="add-hint"]'),
  listCount: document.querySelector('[data-role="list-count"]'),
  habitList: document.querySelector('[data-role="habit-list"]'),
  emptyState: document.querySelector('[data-role="empty-state"]'),
  errorBar: document.querySelector('[data-role="error-bar"]'),
  dialogMask: document.querySelector('[data-role="dialog-mask"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: document.querySelector('[data-role="dialog-confirm"]')
};

let habits = [];
let checkins = {};
let pendingDeleteId = null;

function formatDateKey(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return y + "-" + m + "-" + d;
}

function formatDateLabel(date) {
  const weekdays = ["星期日", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"];
  return date.getFullYear() + " 年 " + (date.getMonth() + 1) + " 月 " + date.getDate() + " 日 · " + weekdays[date.getDay()];
}

function makeId() {
  return "h" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

function normalizeHabit(raw) {
  if (!raw || typeof raw !== "object") return null;
  const id = typeof raw.id === "string" && raw.id ? raw.id : makeId();
  const name = typeof raw.name === "string" ? raw.name : "";
  const createdAt = typeof raw.createdAt === "string" ? raw.createdAt : new Date().toISOString();
  return Object.assign({}, raw, { id: id, name: name, createdAt: createdAt });
}

function normalizeCheckins(raw) {
  const out = {};
  if (!raw || typeof raw !== "object") return out;
  Object.keys(raw).forEach(function (dateKey) {
    const day = raw[dateKey];
    if (!day || typeof day !== "object") return;
    const ids = {};
    Object.keys(day).forEach(function (habitId) {
      if (day[habitId] === true) ids[habitId] = true;
    });
    out[dateKey] = ids;
  });
  return out;
}

function loadFromState() {
  const bucket = state && typeof state === "object" ? state[STORE_KEY] : null;
  if (!bucket || typeof bucket !== "object") {
    habits = [];
    checkins = {};
    return;
  }
  habits = Array.isArray(bucket.habits) ? bucket.habits.map(normalizeHabit).filter(Boolean) : [];
  checkins = normalizeCheckins(bucket.checkins);
}

function isDone(habitId) {
  const day = checkins[todayKey];
  return !!(day && day[habitId] === true);
}

function doneCount() {
  let n = 0;
  habits.forEach(function (h) {
    if (isDone(h.id)) n += 1;
  });
  return n;
}

function showError(message) {
  if (!message) {
    els.errorBar.hidden = true;
    els.errorBar.textContent = "";
    return;
  }
  els.errorBar.hidden = false;
  els.errorBar.textContent = message;
}

function setHint(message) {
  els.addHint.textContent = message || "";
}

async function persist() {
  const prev = (await appStore.getState()) || {};
  const prevBucket = prev && typeof prev[STORE_KEY] === "object" && prev[STORE_KEY] ? prev[STORE_KEY] : {};
  const nextBucket = Object.assign({}, prevBucket, {
    habits: habits,
    checkins: checkins,
    updatedAt: new Date().toISOString()
  });
  const next = Object.assign({}, prev);
  next[STORE_KEY] = nextBucket;
  await appStore.setState(next);
}

function buildCheckIcon() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("class", "check-mark");
  svg.setAttribute("viewBox", "0 0 16 16");
  svg.setAttribute("aria-hidden", "true");
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("d", "M3 8.5 L6.2 11.7 L13 4.5");
  svg.appendChild(path);
  return svg;
}

function render() {
  const total = habits.length;
  const done = doneCount();

  els.todayLabel.textContent = formatDateLabel(new Date());
  els.doneCount.textContent = String(done);
  els.totalCount.textContent = String(total);
  els.listCount.textContent = total + " 个";

  if (total === 0) {
    els.statsSub.textContent = "还没有习惯，先添加一个吧";
  } else if (done === 0) {
    els.statsSub.textContent = "今天还没有开始，加油！";
  } else if (done === total) {
    els.statsSub.textContent = "太棒了，今天全部完成！";
  } else {
    els.statsSub.textContent = "还剩 " + (total - done) + " 个未完成";
  }

  const pct = total === 0 ? 0 : Math.round((done / total) * 100);
  els.progressFill.style.width = pct + "%";

  els.habitList.textContent = "";
  habits.forEach(function (habit) {
    const doneToday = isDone(habit.id);

    const li = document.createElement("li");
    li.className = "habit-item" + (doneToday ? " is-done" : "");
    li.setAttribute("data-habit-id", habit.id);

    const checkBtn = document.createElement("button");
    checkBtn.type = "button";
    checkBtn.className = "check-btn";
    checkBtn.setAttribute("data-action", "toggle");
    checkBtn.setAttribute("aria-pressed", doneToday ? "true" : "false");
    checkBtn.setAttribute("aria-label", (doneToday ? "取消完成：" : "标记完成：") + habit.name);
    checkBtn.appendChild(buildCheckIcon());

    const name = document.createElement("span");
    name.className = "habit-name";
    name.textContent = habit.name;

    const status = document.createElement("span");
    status.className = "habit-status";
    status.textContent = doneToday ? "已完成" : "未完成";

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "del-btn";
    delBtn.setAttribute("data-action", "delete");
    delBtn.setAttribute("aria-label", "删除习惯：" + habit.name);
    delBtn.textContent = "删除";

    li.appendChild(checkBtn);
    li.appendChild(name);
    li.appendChild(status);
    li.appendChild(delBtn);
    els.habitList.appendChild(li);
  });

  els.emptyState.hidden = total !== 0;
}

async function addHabit() {
  const raw = els.habitInput.value;
  const name = raw.trim();

  if (!name) {
    setHint("请输入习惯名称");
    els.habitInput.focus();
    return;
  }
  if (name.length > 30) {
    setHint("习惯名称最多 30 个字");
    return;
  }
  const exists = habits.some(function (h) {
    return h.name === name;
  });
  if (exists) {
    setHint("已经有同名习惯了");
    return;
  }

  const habit = { id: makeId(), name: name, createdAt: new Date().toISOString() };
  const prevHabits = habits.slice();
  habits = habits.concat([habit]);

  try {
    await persist();
  } catch (err) {
    habits = prevHabits;
    render();
    setHint("");
    showError("保存失败，习惯未添加，请重试。");
    return;
  }

  showError("");
  setHint("");
  els.habitInput.value = "";
  render();
  els.habitInput.focus();
}

async function toggleHabit(habitId) {
  const prevCheckins = normalizeCheckins(checkins);
  const day = Object.assign({}, checkins[todayKey] || {});

  if (day[habitId] === true) {
    delete day[habitId];
  } else {
    day[habitId] = true;
  }

  const nextCheckins = Object.assign({}, checkins);
  if (Object.keys(day).length === 0) {
    delete nextCheckins[todayKey];
  } else {
    nextCheckins[todayKey] = day;
  }
  checkins = nextCheckins;

  try {
    await persist();
  } catch (err) {
    checkins = prevCheckins;
    render();
    showError("保存失败，打卡状态未改变，请重试。");
    return;
  }

  showError("");
  render();
}

function openDeleteDialog(habit) {
  pendingDeleteId = habit.id;
  els.dialogText.textContent = "确定要删除习惯「" + habit.name + "」吗？删除后它的打卡记录也会一并移除。";
  els.dialogMask.hidden = false;
  els.dialogConfirm.focus();
}

function closeDeleteDialog() {
  pendingDeleteId = null;
  els.dialogMask.hidden = true;
}

async function confirmDelete() {
  const id = pendingDeleteId;
  if (!id) {
    closeDeleteDialog();
    return;
  }

  const prevHabits = habits.slice();
  const prevCheckins = normalizeCheckins(checkins);

  habits = habits.filter(function (h) {
    return h.id !== id;
  });

  const nextCheckins = {};
  Object.keys(checkins).forEach(function (dateKey) {
    const day = checkins[dateKey];
    const kept = {};
    Object.keys(day).forEach(function (habitId) {
      if (habitId !== id) kept[habitId] = day[habitId];
    });
    if (Object.keys(kept).length > 0) nextCheckins[dateKey] = kept;
  });
  checkins = nextCheckins;

  closeDeleteDialog();

  try {
    await persist();
  } catch (err) {
    habits = prevHabits;
    checkins = prevCheckins;
    render();
    showError("保存失败，习惯未删除，请重试。");
    return;
  }

  showError("");
  render();
}

async function init() {
  loadFromState();
  render();

  els.addBtn.addEventListener("click", function () {
    addHabit();
  });

  els.habitInput.addEventListener("keydown", function (event) {
    if (event.key === "Enter") {
      event.preventDefault();
      addHabit();
    }
  });

  els.habitInput.addEventListener("input", function () {
    setHint("");
  });

  els.habitList.addEventListener("click", function (event) {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const btn = target.closest("button[data-action]");
    if (!btn) return;
    const item = btn.closest("[data-habit-id]");
    if (!item) return;
    const habitId = item.getAttribute("data-habit-id");
    const habit = habits.find(function (h) {
      return h.id === habitId;
    });
    if (!habit) return;

    const action = btn.getAttribute("data-action");
    if (action === "toggle") {
      toggleHabit(habitId);
    } else if (action === "delete") {
      openDeleteDialog(habit);
    }
  });

  els.dialogCancel.addEventListener("click", function () {
    closeDeleteDialog();
  });

  els.dialogConfirm.addEventListener("click", function () {
    confirmDelete();
  });

  els.dialogMask.addEventListener("click", function (event) {
    if (event.target === els.dialogMask) {
      closeDeleteDialog();
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.dialogMask.hidden) {
      closeDeleteDialog();
    }
  });
}

await init();

