:root {
  --bg: #f4f6fb;
  --card: #ffffff;
  --ink: #1f2430;
  --ink-soft: #6b7280;
  --line: #e5e8f0;
  --brand: #4f6ef7;
  --brand-soft: #eaeefe;
  --ok: #17a673;
  --ok-soft: #e6f7f0;
  --danger: #e04b4b;
  --danger-soft: #fdecec;
  --radius: 14px;
}

* {
  box-sizing: border-box;
}

.app-wrap {
  max-width: 560px;
  margin: 0 auto;
  padding: 20px 16px 40px;
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
}

.app-header {
  margin-bottom: 16px;
}

.app-title {
  margin: 0;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.app-date {
  margin: 4px 0 0;
  color: var(--ink-soft);
  font-size: 13px;
}

.stats-card {
  position: relative;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px 16px 20px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: 0 6px 18px rgba(31, 36, 48, 0.05);
  overflow: hidden;
}

.stats-main {
  display: flex;
  align-items: baseline;
  gap: 2px;
  color: var(--brand);
  font-weight: 700;
}

.stats-num {
  font-size: 34px;
  line-height: 1;
}

.stats-sep {
  font-size: 20px;
  color: #b9c0d4;
}

.stats-total {
  font-size: 20px;
  color: var(--ink-soft);
}

.stats-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.stats-sub {
  margin: 2px 0 0;
  font-size: 12px;
  color: var(--ink-soft);
}

.progress-track {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
  background: var(--brand-soft);
}

.progress-fill {
  height: 100%;
  width: 0;
  background: var(--brand);
  transition: width 0.25s ease;
}

.add-card {
  margin-top: 16px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px 16px 12px;
  box-shadow: 0 6px 18px rgba(31, 36, 48, 0.05);
}

.field-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
  margin-bottom: 8px;
}

.add-row {
  display: flex;
  gap: 8px;
}

.text-input {
  flex: 1 1 auto;
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 15px;
  color: var(--ink);
  background: #fbfcfe;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.text-input:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(79, 110, 247, 0.15);
  background: #fff;
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.btn-primary {
  background: var(--brand);
  color: #fff;
}

.btn-primary:hover {
  background: #3f5ce0;
}

.btn-ghost {
  background: #fff;
  border-color: var(--line);
  color: var(--ink);
}

.btn-ghost:hover {
  background: #f2f4fa;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover {
  background: #c93c3c;
}

.hint {
  margin: 8px 0 0;
  min-height: 16px;
  font-size: 12px;
  color: var(--danger);
}

.list-section {
  margin-top: 20px;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}

.list-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
}

.list-count {
  font-size: 12px;
  color: var(--ink-soft);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px 14px;
  box-shadow: 0 4px 12px rgba(31, 36, 48, 0.04);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.habit-item.is-done {
  border-color: #bfe8d8;
  background: var(--ok-soft);
}

.check-btn {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 2px solid #c8cede;
  background: #fff;
  cursor: pointer;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.check-btn:hover {
  border-color: var(--ok);
}

.habit-item.is-done .check-btn {
  border-color: var(--ok);
  background: var(--ok);
}

.check-mark {
  width: 12px;
  height: 12px;
  stroke: #fff;
  stroke-width: 3;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.habit-item.is-done .check-mark {
  opacity: 1;
}

.habit-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 15px;
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: #0f7a56;
  text-decoration: line-through;
  text-decoration-color: rgba(15, 122, 86, 0.4);
}

.habit-status {
  flex: 0 0 auto;
  font-size: 12px;
  color: var(--ink-soft);
}

.habit-item.is-done .habit-status {
  color: var(--ok);
  font-weight: 600;
}

.del-btn {
  flex: 0 0 auto;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--danger);
  border-radius: 8px;
  padding: 5px 10px;
  font-size: 12px;
  cursor: pointer;
  font-family: inherit;
}

.del-btn:hover {
  background: var(--danger-soft);
  border-color: #f3c9c9;
}

.empty-state {
  background: var(--card);
  border: 1px dashed #d5dae8;
  border-radius: var(--radius);
  padding: 28px 18px;
  text-align: center;
}

.empty-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
}

.empty-sub {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.error-bar {
  margin: 16px 0 0;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--danger-soft);
  border: 1px solid #f3c9c9;
  color: #a83232;
  font-size: 13px;
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(20, 24, 34, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-mask[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 340px;
  background: #fff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 18px 40px rgba(20, 24, 34, 0.25);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--ink-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
